import { tags } from "typia";

import { IShoppingMallCartCounts } from "./IShoppingMallCartCounts";
import { IShoppingMallCartValidationFailureDistribution } from "./IShoppingMallCartValidationFailureDistribution";

/**
 * Single bucket within a time-series of cart friction metrics.
 *
 * Represents metrics for a discrete time interval such as a specific hour or
 * day.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallCartFrictionTimeSeriesBucket = {
  /**
   * Inclusive start timestamp for this bucket interval in ISO 8601 date-time
   * format (UTC).
   */
  from: string & tags.Format<"date-time">;

  /**
   * Inclusive end timestamp for this bucket interval in ISO 8601 date-time
   * format (UTC).
   */
  to: string & tags.Format<"date-time">;

  /** Cart population metrics restricted to this bucket interval. */
  cartCounts: IShoppingMallCartCounts;

  /** Validation failure metrics restricted to this bucket interval. */
  validationFailures: IShoppingMallCartValidationFailureDistribution;
};
